    int n, p, k;
    cin >> n >> p >> k;

    int first = max(1, p - k);
    int last = min(n, p + k);

    if (first > 1)
        cout << "<< ";

    for (int i = first; i <= last; ++i) {
        if (i == p)
            cout << '(' << i << ')';
        else
            cout << i;

        if (i < last || last < n)
            cout << ' ';
    }

    if (last < n)
        cout << ">>";

    return 0;
}

