using namespace std;

int main() {
    int n, p, k;
    cin >> n >> p >> k;

    int left = max(1, p - k);
    int right = min(n, p + k);
    bool first = true;

    auto print = [&](const string& value) {
        if (!first) cout << ' ';
        cout << value;
        first = false;
    };

    if (left > 1) print("<<");

    for (int i = left; i <= right; ++i) {
        if (i == p)
            print("(" + to_string(i) + ")");
        else
            print(to_string(i));
    }

    if (right < n) print(">>");

    return 0;
}

