    if (p - k > 1)
        cout << "<< ";

    for (int i = max(1, p - k); i < p; ++i)
        cout << i << " ";

    cout << "(" << p << ")";

    for (int i = p + 1; i <= min(n, p + k); ++i)
        cout << " " << i;

    if (p + k < n)
        cout << " >>";

    return 0;
}

